import { advisoryLock, pool, transaction } from '../../../packages/database/src/pool.js';
import type { ErasureRequestRow } from '../../../packages/privacy/src/erasure.js';

export interface ErasureSubject {
  request: ErasureRequestRow;
  merchantId: string;
  customerId: string;
  email: string;
  name: string;
  phone: string | null;
  externalReference: string;
  providerCustomerIds: string[];
  documents: Array<{ objectKey: string; documentType: string }>;
  importObjects: string[];
}

export class ErasureRepository {
  async createOrResume(merchantId: string, customerId: string, key: string): Promise<ErasureRequestRow | undefined> {
    return await transaction(async (client) => {
      await advisoryLock(client, `erasure-idempotency:${merchantId}:${key}`);
      const replay = await client.query<ErasureRequestRow & { mapped_customer_id: string }>(
        `SELECT request.*,mapping.customer_id mapped_customer_id
         FROM operations.erasure_idempotency_keys mapping
         JOIN operations.erasure_requests request ON request.id=mapping.request_id
         WHERE mapping.merchant_id=$1 AND mapping.key=$2`,
        [merchantId, key],
      );
      if (replay.rows[0]) {
        if (replay.rows[0].mapped_customer_id !== customerId) {
          throw Object.assign(new Error('idempotency_key_conflict'), { statusCode: 409 });
        }
        return await this.resumeFailed(client, replay.rows[0]);
      }

      const existing = await client.query<ErasureRequestRow>(
        `SELECT * FROM operations.erasure_requests WHERE merchant_id=$1 AND customer_id=$2 FOR UPDATE`,
        [merchantId, customerId],
      );
      let request = existing.rows[0];
      if (!request) {
        const customer = await client.query(
          `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2 FOR UPDATE`,
          [merchantId, customerId],
        );
        if (!customer.rowCount) return undefined;
        const created = await client.query<ErasureRequestRow>(
          `INSERT INTO operations.erasure_requests(merchant_id,customer_id)
           VALUES($1,$2) RETURNING *`,
          [merchantId, customerId],
        );
        request = created.rows[0]!;
      } else {
        request = await this.resumeFailed(client, request);
      }

      await client.query(
        `INSERT INTO operations.erasure_idempotency_keys(merchant_id,key,customer_id,request_id)
         VALUES($1,$2,$3,$4)`,
        [merchantId, key, customerId, request.id],
      );
      if (request.status !== 'completed') {
        await client.query(
          `UPDATE customers.customers SET status='erasure_pending',updated_at=now()
           WHERE merchant_id=$1 AND id=$2`,
          [merchantId, customerId],
        );
      }
      return request;
    });
  }

  async find(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT * FROM operations.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE operations.erasure_requests
       SET status='failed',available_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL,
           updated_at=now(),last_error='worker_lease_expired'
       WHERE status='processing' AND lease_expires_at<now()`,
    );
    return result.rowCount ?? 0;
  }

  async claim(workerId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `UPDATE operations.erasure_requests request
       SET status='processing',attempts=request.attempts+1,locked_by=$1,locked_at=now(),
           lease_expires_at=now()+interval '2 minutes',updated_at=now(),last_error=NULL
       WHERE request.id=(SELECT id FROM operations.erasure_requests
         WHERE status IN ('pending','failed') AND available_at<=now()
         ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
       RETURNING request.*`,
      [workerId],
    );
    return result.rows[0];
  }

  async subject(request: ErasureRequestRow): Promise<ErasureSubject | undefined> {
    const result = await pool.query<{
      email: string;
      name: string;
      phone: string | null;
      external_reference: string;
      provider_customer_ids: string[];
      documents: Array<{ objectKey: string; documentType: string }>;
      import_objects: string[];
    }>(
      `SELECT customer.email,customer.name,customer.phone,customer.external_reference,
         ARRAY(SELECT mapping.provider_customer_id FROM customers.provider_customer_mappings mapping
           WHERE mapping.merchant_id=customer.merchant_id AND mapping.customer_id=customer.id) provider_customer_ids,
         COALESCE((SELECT jsonb_agg(jsonb_build_object('objectKey',manifest.object_key,'documentType',manifest.document_type))
           FROM operations.document_manifests manifest
           WHERE manifest.merchant_id=customer.merchant_id AND manifest.customer_id=customer.id),'[]') documents,
         ARRAY(SELECT manifest.object_key FROM operations.document_manifests manifest
           WHERE manifest.merchant_id=customer.merchant_id AND manifest.document_type='customer_import') import_objects
       FROM customers.customers customer WHERE customer.merchant_id=$1 AND customer.id=$2`,
      [request.merchant_id, request.customer_id],
    );
    const row = result.rows[0];
    if (!row) return undefined;
    return {
      request,
      merchantId: request.merchant_id,
      customerId: request.customer_id,
      email: row.email,
      name: row.name,
      phone: row.phone,
      externalReference: row.external_reference,
      providerCustomerIds: row.provider_customer_ids,
      documents: row.documents,
      importObjects: row.import_objects,
    };
  }

  async activeWorkExists(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query<{ active: boolean }>(
      `SELECT EXISTS(
         SELECT 1 FROM operations.email_deliveries
         WHERE merchant_id=$1 AND customer_id=$2 AND status='processing'
         UNION ALL
         SELECT 1 FROM operations.jobs
         WHERE merchant_id=$1 AND payload->>'customerId'=$2 AND status='processing'
         UNION ALL
         SELECT 1 FROM operations.outbox_events
         WHERE merchant_id=$1 AND (aggregate_id=$2 OR payload->>'customerId'=$2) AND status='publishing'
       ) active`,
      [merchantId, customerId],
    );
    return result.rows[0]?.active ?? false;
  }

  async complete(subject: ErasureSubject, workerId: string): Promise<void> {
    await transaction(async (client) => {
      const request = await client.query(
        `SELECT 1 FROM operations.erasure_requests
         WHERE id=$1 AND merchant_id=$2 AND status='processing' AND locked_by=$3 FOR UPDATE`,
        [subject.request.id, subject.merchantId, workerId],
      );
      if (!request.rowCount) throw new Error('erasure lease lost');
      await this.scrubCustomerTables(client, subject);
      await this.scrubFinancialTables(client, subject);
      await this.scrubOperationalTables(client, subject);
      await client.query(
        `UPDATE operations.erasure_requests
         SET status='completed',completed_at=now(),updated_at=now(),last_error=NULL,
             locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
         WHERE id=$1`,
        [subject.request.id],
      );
    });
  }

  async fail(request: ErasureRequestRow, workerId: string, code: string): Promise<void> {
    const delay = Math.min(300, 2 ** Math.min(request.attempts, 8));
    await pool.query(
      `UPDATE operations.erasure_requests
       SET status='failed',last_error=$3,available_at=now()+($4 || ' seconds')::interval,
           updated_at=now(),locked_by=NULL,locked_at=NULL,lease_expires_at=NULL
       WHERE id=$1 AND locked_by=$2`,
      [request.id, workerId, code, delay],
    );
  }

  private async resumeFailed(client: PoolClient, row: ErasureRequestRow): Promise<ErasureRequestRow> {
    if (row.status !== 'failed') return row;
    const result = await client.query<ErasureRequestRow>(
      `UPDATE operations.erasure_requests
       SET status='pending',available_at=now(),updated_at=now(),last_error=NULL
       WHERE id=$1 RETURNING *`,
      [row.id],
    );
    return result.rows[0]!;
  }

  private async scrubCustomerTables(client: PoolClient, subject: ErasureSubject): Promise<void> {
    await client.query(
      `UPDATE customers.support_tickets ticket SET subject='Customer support request'
       WHERE ticket.id IN (SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1)`,
      [subject.customerId],
    );
    await client.query(
      `UPDATE customers.support_messages SET body='[deleted]',attachments='[]'
       WHERE author_type='customer' AND author_id=$1`,
      [subject.customerId],
    );
    await client.query(`DELETE FROM customers.support_participants WHERE customer_id=$1`, [subject.customerId]);
    await client.query(
      `DELETE FROM customers.support_messages message
       WHERE NOT EXISTS(SELECT 1 FROM customers.support_participants participant WHERE participant.ticket_id=message.ticket_id)`,
    );
    await client.query(
      `DELETE FROM customers.support_tickets ticket
       WHERE ticket.merchant_id=$1 AND NOT EXISTS(
         SELECT 1 FROM customers.support_participants participant WHERE participant.ticket_id=ticket.id
       )`,
      [subject.merchantId],
    );
    for (const table of ['addresses', 'contacts', 'payment_method_refs', 'provider_customer_mappings']) {
      await client.query(`DELETE FROM customers.${table} WHERE merchant_id=$1 AND customer_id=$2`, [subject.merchantId, subject.customerId]);
    }
    await client.query(`DELETE FROM customers.customers WHERE merchant_id=$1 AND id=$2`, [subject.merchantId, subject.customerId]);
    await client.query(
      `DELETE FROM provider_sandbox.customers WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [subject.merchantId, subject.customerId],
    );
  }

  private async scrubFinancialTables(client: PoolClient, subject: ErasureSubject): Promise<void> {
    await client.query(
      `UPDATE payments.payment_intents SET customer_snapshot='{}'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [subject.merchantId, subject.customerId],
