      [subject.merchantId, subject.customerId],
    );
    await client.query(
      `UPDATE payments.invoices SET billing_snapshot='{}'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [subject.merchantId, subject.customerId],
    );
    await client.query(
      `UPDATE provider_sandbox.payment_intents SET provider_customer_id=NULL
