import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, ensureBucket, objectStore } from '../../../packages/storage/src/minio.js';
import type { ErasureRequestRow } from '../../../packages/privacy/src/erasure.js';
import { ErasureRepository, type ErasureSubject } from './erasure-repository.js';

class ErasureStepError extends Error {
  constructor(readonly code: string, cause?: unknown) {
    super(code, { cause });
  }
}

export class ErasureService {
  private readonly redis = new Redis(config().REDIS_URL, { lazyConnect: true });

  constructor(private readonly repository = new ErasureRepository()) {}

  async process(request: ErasureRequestRow, workerId: string): Promise<void> {
    const subject = await this.repository.subject(request);
    if (!subject) throw new ErasureStepError('customer_record_missing');
    if (await this.repository.activeWorkExists(subject.merchantId, subject.customerId)) {
      throw new ErasureStepError('active_work_in_progress');
    }

    await this.cleanupDocuments(subject);
    await this.cleanupSearch(subject);
    await this.cleanupCache(subject);
    await this.cleanupEmailProvider(subject);
    try {
      await this.repository.complete(subject, workerId);
    } catch (error) {
      throw new ErasureStepError('database_cleanup_failed', error);
    }
  }

  errorCode(error: unknown): string {
    return error instanceof ErasureStepError ? error.code : 'erasure_failed';
  }

  async close(): Promise<void> {
    if (this.redis.status !== 'wait') await this.redis.quit();
  }

  private async cleanupDocuments(subject: ErasureSubject): Promise<void> {
    try {
      await ensureBucket();
      for (const document of subject.documents) {
        if (document.documentType !== 'invoice' && document.documentType !== 'receipt') continue;
        const original = await this.readObject(document.objectKey);
        const parsed = JSON.parse(original) as Record<string, unknown>;
        delete parsed.customer;
        const body = JSON.stringify(parsed);
        await objectStore.putObject(DOCUMENT_BUCKET, document.objectKey, body, Buffer.byteLength(body), {
          'Content-Type': 'application/json',
        });
        subject.sanitizedDocuments.push({
          objectKey: document.objectKey,
          checksum: createHash('sha256').update(body).digest('hex'),
        });
      }
      for (const objectKey of subject.importObjects) {
        const content = await this.readObject(objectKey);
        if (!this.identifiesSubject(content, subject)) continue;
        await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
        subject.removedImportObjects.push(objectKey);
      }
    } catch (error) {
      throw new ErasureStepError('document_cleanup_failed', error);
    }
  }

  private async cleanupSearch(subject: ErasureSubject): Promise<void> {
    try {
      await searchClient.delete({
        index: CUSTOMER_INDEX,
        id: `${subject.merchantId}:${subject.customerId}`,
        refresh: true,
      });
    } catch (error) {
      if (!this.hasStatus(error, 404)) throw new ErasureStepError('search_cleanup_failed', error);
    }
  }

  private async cleanupCache(subject: ErasureSubject): Promise<void> {
    try {
      if (this.redis.status === 'wait') await this.redis.connect();
      const key = `merchant:${subject.merchantId}:customer:${subject.customerId}`;
      await this.redis.del(key, `${key}:activity`);
    } catch (error) {
      throw new ErasureStepError('cache_cleanup_failed', error);
    }
  }

  private async cleanupEmailProvider(subject: ErasureSubject): Promise<void> {
    try {
      await deleteMailpitMessagesForRecipient(subject.email);
    } catch (error) {
      throw new ErasureStepError('email_provider_cleanup_failed', error);
    }
  }

  private async readObject(objectKey: string): Promise<string> {
    const stream = await objectStore.getObject(DOCUMENT_BUCKET, objectKey);
    const chunks: Buffer[] = [];
    for await (const chunk of stream) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
    return Buffer.concat(chunks).toString('utf8');
  }

  private identifiesSubject(content: string, subject: ErasureSubject): boolean {
    return [subject.customerId, subject.email, subject.externalReference, subject.phone]
      .filter((value): value is string => Boolean(value))
      .some((value) => content.includes(value));
  }

  private hasStatus(error: unknown, status: number): boolean {
    if (!error || typeof error !== 'object') return false;
    const candidate = error as { statusCode?: unknown; meta?: { statusCode?: unknown } };
    return candidate.statusCode === status || candidate.meta?.statusCode === status;
  }
}
